        <dl class="kv"><dt>Endereço</dt><dd class="url">https://${esc(db.config.domain)}/cliente</dd><dt>E-mail</dt><dd>${esc(c.email)}</dd><dt>Código</dt><dd><span class="mono" style="font-size:18px;color:var(--orange-2);letter-spacing:.12em">${c.portalCode}</span></dd></dl>
