  const statusFilter = () => `<label class="sr" for="cst-f">Situação</label><select class="in sm" id="cst-f" style="width:auto"><option value="all">Todas as situações</option>${Object.entries(CST).map(([k, v]) => `<option value="${k}" ${A.contStatus === k ? 'selected' : ''}>${v[0]}</option>`).join('')}</select>`;

